ALTER TABLE inventory_movements ADD COLUMN reserved_before INTEGER NOT NULL DEFAULT 0;
ALTER TABLE inventory ADD COLUMN stock_confirmed INTEGER NOT NULL DEFAULT 1;
ALTER TABLE inventory_movements ADD COLUMN reserved_after INTEGER NOT NULL DEFAULT 0;
ALTER TABLE sales ADD COLUMN number INTEGER;
ALTER TABLE sales ADD COLUMN customer_name TEXT NOT NULL DEFAULT '';
ALTER TABLE sales ADD COLUMN customer_rut TEXT NOT NULL DEFAULT '';
ALTER TABLE sales ADD COLUMN customer_address TEXT NOT NULL DEFAULT '';
ALTER TABLE sales ADD COLUMN payment_method TEXT NOT NULL DEFAULT 'cash';
ALTER TABLE sales ADD COLUMN document_type TEXT NOT NULL DEFAULT 'receipt';
UPDATE sales SET number=rowid;
CREATE UNIQUE INDEX sale_number ON sales(number);
CREATE TABLE orders (id TEXT PRIMARY KEY, number INTEGER NOT NULL UNIQUE, platform TEXT NOT NULL, external_reference TEXT NOT NULL, customer_name TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','packing','packed','cancelled')), stock_policy TEXT NOT NULL CHECK(stock_policy IN ('reserved','deducted')), sale_id TEXT UNIQUE REFERENCES sales(id), actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, packed_at TEXT, UNIQUE(platform,external_reference));
CREATE TABLE order_items (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), variant_id TEXT NOT NULL REFERENCES variants(id), qty INTEGER NOT NULL CHECK(qty>0), checked_qty INTEGER NOT NULL DEFAULT 0 CHECK(checked_qty>=0 AND checked_qty<=qty), source_code TEXT NOT NULL, UNIQUE(order_id,variant_id));
CREATE TABLE packing_events (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), item_id TEXT REFERENCES order_items(id), action TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE INDEX order_status_date ON orders(status,created_at);
CREATE TABLE catalog_import_batches (id TEXT PRIMARY KEY, source TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE catalog_import_rows (id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES catalog_import_batches(id), row_number INTEGER NOT NULL, payload_json TEXT NOT NULL, status TEXT NOT NULL, error TEXT NOT NULL DEFAULT '', variant_id TEXT REFERENCES variants(id));
ALTER TABLE external_codes RENAME TO external_codes_old;
CREATE TABLE external_codes (id TEXT PRIMARY KEY, variant_id TEXT NOT NULL REFERENCES variants(id), platform TEXT NOT NULL CHECK(platform IN ('Dropi','Evolut','Dropea','Jumpseller','Manu')), code TEXT NOT NULL COLLATE NOCASE, origin TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(platform,code), UNIQUE(variant_id,platform));
INSERT INTO external_codes SELECT * FROM external_codes_old;
DROP TABLE external_codes_old;
CREATE INDEX codes_lookup ON external_codes(code);
